#include "RootMotionInterval3D.h"
#include <algorithm>
#include <cmath>
#include <limits>

namespace Aevrynd::RootMotionInternal { namespace {
constexpr double Pi=3.1415926535897932384626433832795;
constexpr double TwoPi=Pi*2.0;
const AnimationTrack3D* FindTrack(const AnimationClip3D& clip,std::size_t root)noexcept{for(const auto& track:clip.tracks)if(track.joint==root)return &track;return nullptr;}
bool Finite(Motion3D v)noexcept{return std::isfinite(v.x)&&std::isfinite(v.y)&&std::isfinite(v.z)&&std::isfinite(v.yaw);}
double RootYaw(const JointTransform3D& value)noexcept{const Matrix4 matrix=value.Matrix();return std::atan2(double(matrix[0][2]),double(matrix[2][2]));}
JointTransform3D SampleTrack(const Skeleton3D& skeleton,const AnimationTrack3D* track,std::size_t root,double time)noexcept{if(!std::isfinite(time)||!track)return skeleton.joints[root].bindTransform;if(time<=0)return track->keyframes.front().transform;if(time>=track->keyframes.back().time)return track->keyframes.back().transform;const auto upper=std::upper_bound(track->keyframes.begin(),track->keyframes.end(),float(time),[](float value,const AnimationKeyframe3D& frame){return value<frame.time;});if(upper==track->keyframes.begin()||upper==track->keyframes.end())return skeleton.joints[root].bindTransform;const auto& to=*upper;const auto& from=*(upper-1);return InterpolateJointTransform(from.transform,to.transform,float((time-from.time)/(to.time-from.time)));}
Motion3D Between(const JointTransform3D& from,const JointTransform3D& to,bool vertical)noexcept{const double yaw=RootYaw(from),c=std::cos(yaw),s=std::sin(yaw),dx=double(to.translation.x)-from.translation.x,dz=double(to.translation.z)-from.translation.z;return{c*dx-s*dz,vertical?double(to.translation.y)-from.translation.y:0,s*dx+c*dz,NormalizeYaw(RootYaw(to)-yaw)};}
Motion3D WithinCycle(const Skeleton3D& skeleton,const AnimationTrack3D* track,std::size_t root,double from,double to,bool vertical)noexcept{Motion3D total{};double cursor=from;if(track)for(const auto& key:track->keyframes)if(key.time>from&&key.time<to){total=Compose(total,Between(SampleTrack(skeleton,track,root,cursor),key.transform,vertical));cursor=key.time;}return Compose(total,Between(SampleTrack(skeleton,track,root,cursor),SampleTrack(skeleton,track,root,to),vertical));}
bool Cycle(double time,double duration,std::int64_t& cycle)noexcept{const double value=std::floor(time/duration);constexpr double ExactIntegerLimit=9007199254740992.0;if(!std::isfinite(value)||value<-ExactIntegerLimit||value>ExactIntegerLimit)return false;cycle=std::int64_t(value);return true;}
bool Forward(const Skeleton3D& skeleton,const AnimationTrack3D* track,std::size_t root,double duration,double from,double to,std::uint32_t maximum,bool vertical,Motion3D& output,std::int64_t& crossed)noexcept{std::int64_t fromCycle{},toCycle{};if(!Cycle(from,duration,fromCycle)||!Cycle(to,duration,toCycle)||toCycle<fromCycle)return false;const std::uint64_t span=std::uint64_t(toCycle)-std::uint64_t(fromCycle);if(span>maximum)return false;crossed=std::int64_t(span);const double fromPhase=WrappedPhase(from,duration),toPhase=WrappedPhase(to,duration);if(!crossed){output=WithinCycle(skeleton,track,root,fromPhase,toPhase,vertical);return Finite(output);}Motion3D total=WithinCycle(skeleton,track,root,fromPhase,duration,vertical),cycle=WithinCycle(skeleton,track,root,0,duration,vertical);for(std::int64_t index=1;index<crossed;++index)total=Compose(total,cycle);output=Compose(total,WithinCycle(skeleton,track,root,0,toPhase,vertical));return Finite(output);}
void SplitQ32(std::int64_t value,std::int64_t& cycle,std::uint32_t& phase)noexcept{constexpr std::int64_t Scale=std::int64_t{1}<<32;cycle=value/Scale;std::int64_t remainder=value%Scale;if(remainder<0){remainder+=Scale;--cycle;}phase=std::uint32_t(remainder);}
bool ForwardQ32(const Skeleton3D& skeleton,const AnimationTrack3D* track,std::size_t root,double duration,std::int64_t from,std::int64_t to,std::uint32_t maximum,bool vertical,Motion3D& output,std::int64_t& crossed)noexcept{std::int64_t fromCycle{},toCycle{};std::uint32_t fromFraction{},toFraction{};SplitQ32(from,fromCycle,fromFraction);SplitQ32(to,toCycle,toFraction);if(toCycle<fromCycle)return false;const std::uint64_t span=std::uint64_t(toCycle)-std::uint64_t(fromCycle);if(span>maximum)return false;crossed=std::int64_t(span);const double fromPhase=std::ldexp(double(fromFraction),-32)*duration,toPhase=std::ldexp(double(toFraction),-32)*duration;if(!crossed){output=WithinCycle(skeleton,track,root,fromPhase,toPhase,vertical);return Finite(output);}Motion3D total=WithinCycle(skeleton,track,root,fromPhase,duration,vertical),cycle=WithinCycle(skeleton,track,root,0,duration,vertical);for(std::int64_t index=1;index<crossed;++index)total=Compose(total,cycle);output=Compose(total,WithinCycle(skeleton,track,root,0,toPhase,vertical));return Finite(output);}
}

double NormalizeYaw(double value)noexcept{value=std::fmod(value,TwoPi);if(value>Pi)value-=TwoPi;if(value<=-Pi)value+=TwoPi;return value==0?0:value;}
double WrappedPhase(double time,double duration)noexcept{if(!std::isfinite(time)||!std::isfinite(duration)||duration<=0)return (std::numeric_limits<double>::quiet_NaN)();double phase=std::fmod(time,duration);if(phase<0)phase+=duration;return phase==0?0:phase;}
bool NormalizedClockToQ32(double value,std::int64_t& output)noexcept{constexpr double Limit=2147483648.0;if(!std::isfinite(value)||value<-Limit||value>=Limit)return false;const double rounded=std::round(std::ldexp(value,32));if(!std::isfinite(rounded)||rounded>=std::ldexp(1.0,63)||rounded<std::ldexp(-1.0,63))return false;output=static_cast<std::int64_t>(rounded);return true;}
bool AdvanceNormalizedClockQ32(std::int64_t current,double delta,std::int64_t& output)noexcept{std::int64_t increment{};if(!NormalizedClockToQ32(delta,increment))return false;if((increment>0&&current>(std::numeric_limits<std::int64_t>::max)()-increment)||(increment<0&&current<(std::numeric_limits<std::int64_t>::min)()-increment))return false;output=current+increment;return true;}
double WrappedPhaseQ32(std::int64_t value)noexcept{std::int64_t cycle{};std::uint32_t phase{};SplitQ32(value,cycle,phase);return std::ldexp(double(phase),-32);}
Motion3D Compose(Motion3D a,Motion3D b)noexcept{const double c=std::cos(a.yaw),s=std::sin(a.yaw);return{a.x+c*b.x+s*b.z,a.y+b.y,a.z-s*b.x+c*b.z,NormalizeYaw(a.yaw+b.yaw)};}
Motion3D Inverse(Motion3D value)noexcept{const double c=std::cos(value.yaw),s=std::sin(value.yaw);return{-c*value.x+s*value.z,-value.y,-s*value.x-c*value.z,NormalizeYaw(-value.yaw)};}
bool ValidateRootTrack(const AnimationClip3D& clip,std::size_t root)noexcept{const auto* track=FindTrack(clip,root);if(!track)return true;if(track->keyframes.empty()||track->keyframes.front().time!=0.f||track->keyframes.back().time!=clip.duration)return false;float previous=-1;for(const auto& frame:track->keyframes){if(frame.time<=previous)return false;previous=frame.time;}return true;}
JointTransform3D SampleRootTransform(const Skeleton3D& skeleton,const AnimationClip3D& clip,std::size_t root,double wrappedTime)noexcept{return SampleTrack(skeleton,FindTrack(clip,root),root,wrappedTime);}
bool ExtractInterval(const Skeleton3D& skeleton,const AnimationClip3D& clip,std::size_t root,double from,double to,std::uint32_t maximum,bool vertical,Motion3D& output,std::int64_t& crossed)noexcept{output={};crossed=0;if(!clip.Valid(skeleton)||root>=skeleton.joints.size()||skeleton.joints[root].parent!=-1||!ValidateRootTrack(clip,root)||!maximum||!std::isfinite(from)||!std::isfinite(to))return false;const auto* track=FindTrack(clip,root);if(!clip.looping){const double a=std::clamp(from,0.0,double(clip.duration)),b=std::clamp(to,0.0,double(clip.duration));output=a<=b?WithinCycle(skeleton,track,root,a,b,vertical):Inverse(WithinCycle(skeleton,track,root,b,a,vertical));return Finite(output);}if(to>=from)return Forward(skeleton,track,root,clip.duration,from,to,maximum,vertical,output,crossed);std::int64_t reverse{};if(!Forward(skeleton,track,root,clip.duration,to,from,maximum,vertical,output,reverse))return false;output=Inverse(output);crossed=-reverse;return Finite(output);}
bool ExtractIntervalQ32(const Skeleton3D& skeleton,const AnimationClip3D& clip,std::size_t root,std::int64_t from,std::int64_t to,std::uint32_t maximum,bool vertical,Motion3D& output,std::int64_t& crossed)noexcept{output={};crossed=0;if(!clip.Valid(skeleton)||root>=skeleton.joints.size()||skeleton.joints[root].parent!=-1||!ValidateRootTrack(clip,root)||!maximum)return false;const auto* track=FindTrack(clip,root);if(!clip.looping){constexpr std::int64_t OneQ32=std::int64_t{1}<<32;const auto time=[&](std::int64_t value){if(value<=0)return 0.0;if(value>=OneQ32)return double(clip.duration);return std::ldexp(double(value),-32)*clip.duration;};const double a=time(from),b=time(to);output=a<=b?WithinCycle(skeleton,track,root,a,b,vertical):Inverse(WithinCycle(skeleton,track,root,b,a,vertical));return Finite(output);}if(to>=from)return ForwardQ32(skeleton,track,root,clip.duration,from,to,maximum,vertical,output,crossed);std::int64_t reverse{};if(!ForwardQ32(skeleton,track,root,clip.duration,to,from,maximum,vertical,output,reverse))return false;output=Inverse(output);crossed=-reverse;return Finite(output);}
bool LogSE2(Motion3D motion,Twist3D& output)noexcept{if(!Finite(motion))return false;const double w=NormalizeYaw(motion.yaw),w2=w*w;double a{},b{};if(std::abs(w)<1e-6){a=1-w2/6+w2*w2/120;b=w/2-w*w2/24+w*w2*w2/720;}else{a=std::sin(w)/w;b=(1-std::cos(w))/w;}const double determinant=a*a+b*b;if(!std::isfinite(determinant)||determinant<=std::numeric_limits<double>::epsilon())return false;output={(a*motion.x-b*motion.z)/determinant,motion.y,(b*motion.x+a*motion.z)/determinant,w};return std::isfinite(output.x)&&std::isfinite(output.y)&&std::isfinite(output.z)&&std::isfinite(output.yaw);}
bool ExpSE2(Twist3D twist,Motion3D& output)noexcept{if(!std::isfinite(twist.x)||!std::isfinite(twist.y)||!std::isfinite(twist.z)||!std::isfinite(twist.yaw))return false;const double w=NormalizeYaw(twist.yaw),w2=w*w;double a{},b{};if(std::abs(w)<1e-6){a=1-w2/6+w2*w2/120;b=w/2-w*w2/24+w*w2*w2/720;}else{a=std::sin(w)/w;b=(1-std::cos(w))/w;}output={a*twist.x+b*twist.z,twist.y,-b*twist.x+a*twist.z,w};if(output.x==0)output.x=0;if(output.y==0)output.y=0;if(output.z==0)output.z=0;if(output.yaw==0)output.yaw=0;return Finite(output);}
}
